/* Cours longs — Histologie / Embryologie. */
const P = (t) => `<p class="mb-3">${t}</p>`;
const H = (t) => `<h4 class="text-lg font-semibold text-gray-800 mb-2">${t}</h4>`;
const UL = (a) => `<ul class="list-disc pl-5 space-y-1 mb-4 text-gray-700">${a.map((i) => `<li>${i}</li>`).join('')}</ul>`;
const KEY = (t) => `<div class="bg-fuchsia-50 border border-fuchsia-200 rounded-xl p-4 mt-4"><p class="text-sm font-semibold text-fuchsia-800">Point clé PASS/LAS : ${t}</p></div>`;
const TABLE = (head, rows) => `<div class="overflow-x-auto mb-4"><table class="w-full text-sm border border-gray-200 rounded-xl overflow-hidden"><thead class="bg-gray-50"><tr>${head.map((h) => `<th class="text-left px-3 py-2 font-semibold text-gray-700">${h}</th>`).join('')}</tr></thead><tbody>${rows.map((r) => `<tr class="border-t border-gray-100">${r.map((c) => `<td class="px-3 py-2 text-gray-700">${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;

export const COURS_HISTO = {
  'histo-epitheliums': { introduction: "Les épithéliums couvrent toutes les surfaces du corps et forment toutes les glandes. Ce cours en donne les caractères généraux, la classification complète avec ses exemples, les spécialisations de surface et l'organisation des glandes exocrines et endocrines.", readTime: 24, sections: [
    { title: 'Caractères généraux des épithéliums', content: P("Un <strong>épithélium</strong> est un tissu formé de cellules <strong>jointives</strong>, étroitement accolées par des jonctions, avec très peu de matrice extracellulaire, organisées en une ou plusieurs couches et reposant sur une <strong>lame basale</strong> qui les sépare du tissu conjonctif sous-jacent. Les épithéliums <strong>ne sont pas vascularisés</strong> : oxygène et nutriments diffusent depuis les capillaires du conjonctif à travers la lame basale. Ils sont innervés (terminaisons sensitives libres) et se renouvellent rapidement à partir de cellules souches basales (intestin : 3 à 5 jours ; épiderme : 4 semaines).") + H('Polarité') + P("Les cellules épithéliales ont un <strong>pôle apical</strong> tourné vers la surface libre ou la lumière, un pôle <strong>basal</strong> sur la lame basale et des faces latérales jointives. Cette polarité se traduit par une répartition asymétrique des organites, des transporteurs et des jonctions : par exemple, les entérocytes portent SGLT1 au pôle apical et GLUT2 et la Na+/K+ ATPase au pôle basolatéral, ce qui rend le transport vectoriel possible.") + H('Lame basale et membrane basale') + P("La <strong>lame basale</strong>, sécrétée par les cellules épithéliales, comprend une lamina lucida et une lamina densa faites de <strong>collagène IV</strong>, de <strong>laminine</strong>, de nidogène et de perlécan (protéoglycane). Le tissu conjonctif y ajoute une lamina fibroreticularis (collagène III, VII) : l'ensemble constitue la <strong>membrane basale</strong>, visible en microscopie optique (PAS positive). Elle sert d'ancrage (hémidesmosomes, intégrines), de filtre sélectif (glomérule rénal), de guide à la régénération et de barrière que les cancers doivent franchir pour devenir invasifs (carcinome in situ vs infiltrant).") + H('Origine embryologique') + P("Les épithéliums dérivent des trois feuillets : ectoderme (épiderme, épithélium cornéen, émail, glandes mammaires et sudoripares), endoderme (tube digestif et ses glandes, arbre respiratoire, thyroïde, vessie), mésoderme (endothélium, mésothélium, épithéliums rénaux et génitaux). Le mot « endothélium » désigne l'épithélium des vaisseaux, « mésothélium » celui des séreuses (plèvre, péritoine, péricarde).") + KEY("Jointives, polarisées, sur une lame basale, sans vaisseaux, à renouvellement rapide : cinq caractères qui distinguent un épithélium d'un tissu conjonctif. Le franchissement de la membrane basale définit le cancer invasif.") },
    { title: 'Jonctions et spécialisations de surface', content: H('Le complexe de jonction') + TABLE(['Jonction', 'Structure', 'Fonction', 'Localisation'], [['Serrée (zonula occludens)', 'claudines et occludines fusionnant les membranes en ceinture', 'étanchéité paracellulaire, maintien de la polarité (barrière apico-basolatérale)', 'la plus apicale ; intestin, rein, barrière hémato-encéphalique'], ['Adhérente (zonula adherens)', 'cadhérines (E-cadhérine) liées à l’actine par les caténines', 'adhésion en ceinture, transmission des forces, morphogenèse', 'sous la jonction serrée'], ['Desmosome (macula adherens)', 'desmogléines et desmocollines, plaque avec desmoplakine, filaments intermédiaires de kératine', 'adhésion ponctuelle résistante à la traction', 'épithéliums soumis à contrainte (épiderme, myocarde)'], ['Communicante (gap)', 'connexons de 6 connexines, canal de 1,5 nm', 'passage d’ions et petites molécules (&lt; 1 kDa), couplage électrique et métabolique', 'myocarde, muscle lisse, épithéliums, os'], ['Hémidesmosome', 'intégrines α6β4 et plaque, kératines', 'ancrage à la lame basale', 'pôle basal']]) + P("Pathologies : le <strong>pemphigus</strong> (anticorps anti-desmogléine, bulles intra-épidermiques) et la <strong>pemphigoïde</strong> (anticorps anti-hémidesmosome, bulles sous-épidermiques) ; la perte d'E-cadhérine favorise la dissémination des cancers ; les mutations des connexines causent des surdités.") + H('Spécialisations apicales') + UL(["<strong>Microvillosités</strong> : expansions de 1 µm soutenues par de l'actine (villine, fimbrine), multipliant la surface d'absorption par 20 : <strong>bordure en brosse</strong> de l'intestin et du tube proximal rénal. Recouvertes du glycocalyx portant les enzymes de bordure.", "<strong>Cils</strong> : 5-10 µm, axonème de 9 doublets de microtubules + 2 centraux, bras de dynéine, corpuscule basal ; battement coordonné qui déplace le mucus (voies respiratoires : escalator mucociliaire) ou l'ovocyte (trompe). Dyskinésie ciliaire primitive (syndrome de Kartagener : infections, stérilité, situs inversus). Le <strong>cil primaire</strong>, unique et immobile (9 + 0), est un capteur présent sur presque toutes les cellules (polykystose rénale).", "<strong>Stéréocils</strong> : longues microvillosités immobiles (épididyme : absorption ; oreille interne : mécanotransduction).", "<strong>Flagelle</strong> du spermatozoïde : structure ciliaire unique et longue."]) + KEY("Jonction serrée = étanchéité, adhérente et desmosome = cohésion, gap = communication. Microvillosités = actine, absorption ; cils = microtubules, mouvement. Ne pas confondre stéréocils (actine, immobiles) et cils (microtubules, mobiles).") },
    { title: 'Classification des épithéliums de revêtement', content: P("Deux critères : le <strong>nombre de couches</strong> (simple : une couche, toutes les cellules touchent la lame basale et la surface ; stratifié : plusieurs couches, seule la couche basale touche la lame basale ; pseudostratifié : une seule couche dont toutes les cellules touchent la lame basale mais pas toutes la surface, noyaux à des hauteurs différentes) et la <strong>forme des cellules</strong> de la couche superficielle (pavimenteuses ou squameuses : plates ; cubiques ; prismatiques ou cylindriques : plus hautes que larges).") + TABLE(['Épithélium', 'Localisation', 'Fonction'], [['Pavimenteux simple', 'endothélium des vaisseaux, mésothélium des séreuses, alvéoles pulmonaires (pneumocytes I), capsule de Bowman, anse de Henle', 'échanges, diffusion, glissement'], ['Cubique simple', 'tubes rénaux, follicules thyroïdiens, canaux excréteurs des glandes, épithélium pigmentaire de la rétine, surface de l’ovaire', 'sécrétion, absorption'], ['Prismatique simple', 'estomac (à pôle muqueux fermé), intestin grêle et côlon (à bordure en brosse et cellules caliciformes), vésicule biliaire, trompe et utérus (cilié)', 'absorption, sécrétion'], ['Pseudostratifié prismatique cilié', 'trachée, bronches, fosses nasales (épithélium respiratoire, avec cellules caliciformes) ; épididyme (à stéréocils, non cilié)', 'transport du mucus'], ['Pavimenteux stratifié non kératinisé', 'cavité buccale, œsophage, cordes vocales, vagin, exocol, cornée', 'protection des surfaces humides soumises à frottement'], ['Pavimenteux stratifié kératinisé', 'épiderme (couches basale, épineuse, granuleuse, claire aux paumes et plantes, cornée)', 'protection, imperméabilité'], ['Cubique ou prismatique stratifié', 'canaux des glandes sudoripares et salivaires (rares)', 'conduction'], ['Urothélium (transition, polymorphe)', 'calices, bassinet, uretères, vessie, urètre proximal', 'distensible, imperméable à l’urine (cellules en ombrelle, plaques d’uroplakine)']]) + P("Les <strong>cellules caliciformes</strong> sont des glandes unicellulaires à mucus dispersées dans l'intestin et l'arbre respiratoire. La <strong>jonction</strong> entre deux épithéliums différents (œsophage-estomac, exocol-endocol, anorectale) est une zone de transition fragile, siège fréquent de métaplasie et de cancer.") + H('Métaplasie, dysplasie') + P("La <strong>métaplasie</strong> est le remplacement réversible d'un épithélium différencié par un autre, adapté à une agression chronique : épithélium respiratoire devenant pavimenteux stratifié chez le fumeur, muqueuse œsophagienne devenant glandulaire gastrique dans le reflux (endobrachyœsophage). La <strong>dysplasie</strong> associe des anomalies cytologiques et architecturales sans franchissement de la membrane basale : lésion précancéreuse (frottis cervical, dépistage du cancer du col lié aux papillomavirus).") + KEY("Simple pour échanger et absorber, stratifié pour protéger, pseudostratifié cilié pour les voies respiratoires, urothélium pour les voies urinaires. Le nom décrit la couche superficielle : un épithélium stratifié « pavimenteux » a des cellules basales cubiques.") },
    { title: 'Épithéliums glandulaires', content: P("Les <strong>glandes</strong> naissent d'un bourgeon épithélial qui s'enfonce dans le conjonctif. Si la connexion avec la surface persiste sous forme de canal, la glande est <strong>exocrine</strong> ; si elle disparaît et que les cellules s'organisent au contact des capillaires, la glande est <strong>endocrine</strong> et sécrète dans le sang.") + H('Glandes exocrines') + UL(["<strong>Unicellulaires</strong> : cellules caliciformes. <strong>Multicellulaires</strong> : intra-épithéliales ou, le plus souvent, extra-épithéliales avec une portion sécrétrice (adénomère) et un canal.", "Selon la forme de l'adénomère : <strong>tubuleuse</strong> (glandes de Lieberkühn, sudoripares : tubuleuse contournée), <strong>acineuse</strong> ou alvéolaire (pancréas, parotide, glandes sébacées), <strong>tubulo-acineuse</strong> (glandes sous-maxillaires, mammaires). Selon le canal : simple (non ramifié) ou composée (ramifié).", "Selon le produit : <strong>séreuse</strong> (protéines enzymatiques, cellules pyramidales à noyau rond basal, grains de zymogène : parotide, pancréas), <strong>muqueuse</strong> (mucines, cellules claires à noyau aplati basal : glandes de Brunner, glandes palatines), <strong>mixte</strong> séro-muqueuse avec croissants séreux de Gianuzzi (sous-maxillaire, sublinguale).", "Selon le mode d'excrétion : <strong>mérocrine</strong> (exocytose sans perte cellulaire : la quasi-totalité), <strong>apocrine</strong> (élimination d'une partie du cytoplasme apical : glande mammaire pour les lipides, glandes sudoripares apocrines), <strong>holocrine</strong> (la cellule entière se charge de produit, meurt et est éliminée : glandes sébacées).", "Les <strong>cellules myoépithéliales</strong>, contractiles, entre l'adénomère et la lame basale, expulsent la sécrétion (glandes salivaires, sudoripares, mammaires)."]) + H('Glandes endocrines') + P("Sans canal, richement vascularisées par des capillaires fenêtrés. Organisation en <strong>cordons</strong> ou travées (surrénale, antéhypophyse, parathyroïdes, îlots de Langerhans, foie pour sa fonction endocrine) ou en <strong>vésicules</strong> (thyroïde : follicules remplis de colloïde, seul exemple de stockage extracellulaire d'une hormone). Les cellules sécrétant des hormones peptidiques ont un réticulum granuleux et des grains de sécrétion ; celles sécrétant des stéroïdes (corticosurrénale, cellules de Leydig, corps jaune) ont un réticulum lisse abondant, des mitochondries à crêtes tubulaires et des inclusions lipidiques, sans grains de stockage. Le <strong>système endocrinien diffus</strong> (cellules neuroendocrines du tube digestif et des bronches, dispersées dans l'épithélium) sécrète gastrine, sécrétine, sérotonine, CCK.") + P("Les glandes <strong>amphicrines</strong> exercent les deux fonctions : le pancréas (acini exocrines, îlots endocrines) et le foie (bile exocrine, protéines et facteurs plasmatiques endocrines), avec pour ce dernier une organisation particulière en travées d'hépatocytes autour des sinusoïdes.") + KEY("Exocrine = canal, endocrine = sang. Mérocrine (exocytose) pour presque toutes, apocrine pour le lait, holocrine pour le sébum. Séreux = enzymes et noyau rond ; muqueux = mucus et noyau aplati au pôle basal.") },
  ] },

  'histo-conjonctif': { introduction: "Les tissus conjonctifs relient, soutiennent, nourrissent et défendent. Ce cours décrit leurs trois composants, leurs variétés, puis les deux tissus conjonctifs spécialisés du squelette : le cartilage et l'os, avec leur croissance et leur remodelage.", readTime: 26, sections: [
    { title: 'Composition des tissus conjonctifs', content: P("À l'inverse des épithéliums, les tissus conjonctifs comportent des cellules <strong>dispersées</strong> dans une <strong>matrice extracellulaire</strong> abondante, qu'elles synthétisent. Ils sont <strong>vascularisés</strong> (sauf le cartilage) et innervés, et dérivent tous du <strong>mésenchyme</strong> embryonnaire (mésoderme, et crêtes neurales pour la tête).") + H('Les cellules') + UL(["<strong>Fibroblastes</strong> : cellules résidentes principales, fusiformes, synthétisent le collagène, l'élastine et la substance fondamentale ; deviennent fibrocytes au repos, myofibroblastes (contractiles) dans la cicatrisation.", "<strong>Adipocytes</strong>, <strong>cellules mésenchymateuses</strong> indifférenciées (réserve, péricytes), <strong>chondroblastes et ostéoblastes</strong> dans les tissus spécialisés.", "Cellules d'origine sanguine : <strong>macrophages</strong> (histiocytes : phagocytose, présentation d'antigène, dérivés des monocytes), <strong>mastocytes</strong> (granulations d'histamine et d'héparine, récepteurs IgE : allergie, anaphylaxie), <strong>plasmocytes</strong> (lymphocytes B différenciés, noyau en roue, sécrétion d'anticorps), lymphocytes, polynucléaires en cas d'inflammation."]) + H('Les fibres') + TABLE(['Fibre', 'Composition', 'Propriétés', 'Localisation'], [['Collagène I', 'triple hélice, fibrilles striées, fibres épaisses', 'résistance à la traction, inextensible ; 90 % du collagène', 'derme, tendons, ligaments, os, cornée, dentine'], ['Collagène II', 'fibrilles fines', 'résistance à la compression', 'cartilage hyalin et élastique, nucleus pulposus, vitré'], ['Collagène III (réticuline)', 'fibrilles fines argyrophiles en réseau', 'charpente délicate', 'organes lymphoïdes, moelle, foie, rate, autour des vaisseaux et des adipocytes'], ['Collagène IV', 'réseau non fibrillaire', 'filtration, ancrage', 'lame basale'], ['Élastiques', 'élastine (désmosine) sur un réseau de fibrilline', 'extensibles (150 %) et rétractiles', 'aorte, poumon, peau, ligaments jaunes, cartilage élastique']]) + P("Le collagène est synthétisé sous forme de procollagène (hydroxylation de la proline et de la lysine, dépendante de la <strong>vitamine C</strong> : le scorbut donne des hémorragies gingivales et des retards de cicatrisation), sécrété, clivé, puis assemblé en fibrilles stabilisées par des ponts covalents (lysyl-oxydase). Maladies : ostéogenèse imparfaite (collagène I), Ehlers-Danlos (hyperlaxité), Marfan (fibrilline : dissection aortique, luxation du cristallin, grande taille).") + H('La substance fondamentale') + P("Gel hydraté, amorphe, fait de <strong>glycosaminoglycanes</strong> (acide hyaluronique non sulfaté, très long ; chondroïtine, dermatane, kératane et héparane sulfates), assemblés en <strong>protéoglycanes</strong> (aggrécane du cartilage, décorine, perlécan) sur un axe protéique, et de <strong>glycoprotéines d'adhérence</strong> (fibronectine, laminine, ténascine) qui relient cellules et fibres via les intégrines. Chargée négativement, elle retient l'eau (turgescence, résistance à la compression), laisse diffuser les nutriments et freine les bactéries (les hyaluronidases bactériennes lèvent cet obstacle).") + KEY("Trois composants : cellules (fibroblaste au centre), fibres (collagène I pour la traction, élastine pour le retour, réticuline pour la charpente) et substance fondamentale (GAG et protéoglycanes qui retiennent l'eau). Vascularisé, à l'inverse de l'épithélium.") },
    { title: 'Variétés de tissus conjonctifs', content: TABLE(['Variété', 'Caractères', 'Localisation'], [['Lâche (aréolaire)', 'cellules variées, fibres peu denses, substance fondamentale abondante, très vascularisé', 'chorion des muqueuses, sous-cutané, autour des vaisseaux et des nerfs, stroma des organes ; siège de l’inflammation'], ['Dense régulier', 'faisceaux de collagène I parallèles, fibroblastes alignés, peu vascularisé', 'tendons, ligaments, aponévroses, cornée'], ['Dense irrégulier', 'faisceaux entrecroisés', 'derme réticulaire, capsules des organes, périoste, dure-mère'], ['Élastique', 'fibres élastiques dominantes', 'ligaments jaunes, média de l’aorte, ligament nucal'], ['Réticulé', 'réseau de réticuline et cellules réticulaires', 'organes lymphoïdes, moelle osseuse, foie'], ['Muqueux', 'substance fondamentale gélatineuse, peu de fibres', 'gelée de Wharton du cordon ombilical, pulpe dentaire'], ['Adipeux blanc', 'adipocytes uniloculaires (une vacuole, noyau refoulé), réticuline, très vascularisé', 'hypoderme, mésentère, périrénal : réserve d’énergie, isolation, endocrine (leptine, adiponectine)'], ['Adipeux brun', 'adipocytes multiloculaires, mitochondries riches en UCP1 (thermogénine), innervation sympathique', 'nouveau-né (interscapulaire), persiste en petite quantité chez l’adulte (cou, médiastin) : thermogenèse sans frisson']]) + H('Inflammation et cicatrisation') + P("Le tissu conjonctif lâche est le théâtre de la réaction inflammatoire : vasodilatation, exsudation (œdème), diapédèse des polynucléaires puis des monocytes, activation des mastocytes et des macrophages. La <strong>cicatrisation</strong> passe par un tissu de granulation (néovaisseaux, fibroblastes, macrophages), la prolifération des fibroblastes et la synthèse de collagène III puis I, la contraction par les myofibroblastes, et aboutit à une cicatrice fibreuse (perte de fonction dans le myocarde, le SNC). Cicatrices hypertrophiques et chéloïdes traduisent un excès de collagène.") + KEY("Lâche = chorion et inflammation ; dense régulier = tendon ; réticulé = organes lymphoïdes ; adipeux brun = thermogenèse par UCP1. Le tissu adipeux est un organe endocrine à part entière.") },
    { title: 'Le cartilage', content: P("Tissu conjonctif spécialisé, ferme mais déformable, <strong>avasculaire</strong>, non innervé, sans lymphatiques : les <strong>chondrocytes</strong>, logés dans des <strong>chondroplastes</strong> (logettes), sont nourris par diffusion à partir du <strong>périchondre</strong> (conjonctif dense vascularisé qui entoure le cartilage, sauf articulaire) ou du liquide synovial. D'où une réparation médiocre et une intolérance aux pressions excessives.") + H('Matrice') + P("Collagène de <strong>type II</strong> (fibrilles fines masquées dans la substance fondamentale), <strong>aggrécane</strong> (protéoglycane géant à chondroïtine et kératane sulfate, agrégé sur l'acide hyaluronique) très hydrophile : le cartilage contient 70 % d'eau et résiste à la compression comme une éponge sous pression. La matrice territoriale, autour des chondrocytes, est basophile ; les chondrocytes en division forment des groupes isogéniques.") + H('Croissance') + UL(["<strong>Appositionnelle</strong> : les cellules de la couche interne du périchondre se différencient en chondroblastes et déposent du cartilage en périphérie.", "<strong>Interstitielle</strong> : les chondrocytes se divisent et sécrètent de la matrice de l'intérieur (groupes isogéniques axiaux ou coronaires) ; possible seulement parce que la matrice est déformable ; c'est le mode de croissance du cartilage de conjugaison."]) + H('Les trois types') + TABLE(['Type', 'Caractères', 'Localisation'], [['Hyalin', 'le plus fréquent, matrice homogène bleutée, collagène II, périchondre sauf articulaire', 'squelette fœtal, cartilage de conjugaison, cartilages articulaires, costaux, nasal, laryngé, trachéal et bronchique'], ['Élastique', 'collagène II + réseau de fibres élastiques, périchondre, ne se calcifie pas', 'pavillon de l’oreille, conduit auditif, épiglotte, petits cartilages du larynx'], ['Fibreux (fibrocartilage)', 'faisceaux de collagène I visibles, chondrocytes en files, pas de périchondre, intermédiaire entre tendon et cartilage', 'disques intervertébraux (anneau fibreux), ménisques, symphyse pubienne, insertions tendineuses, labrum']]) + P("Avec l'âge, le cartilage hyalin se calcifie et les chondrocytes meurent ; l'<strong>arthrose</strong> est une dégradation du cartilage articulaire (perte d'aggrécane, fissures, ostéophytes), peu réparable puisque le tissu ne se régénère pas.") + KEY("Cartilage = avasculaire, nourri par le périchondre, collagène II, aggrécane et eau. Hyalin partout, élastique dans l'oreille et l'épiglotte, fibreux dans les disques et les ménisques. Le cartilage articulaire n'a pas de périchondre : il ne cicatrise pas.") },
    { title: 'Le tissu osseux', content: P("Tissu conjonctif spécialisé dont la matrice est <strong>minéralisée</strong> : 65 % de cristaux d'<strong>hydroxyapatite</strong> de calcium déposés sur une trame de collagène I (ostéoïde) avec des protéines non collagéniques (ostéocalcine, ostéopontine). Rigide mais vivant, richement vascularisé, en remodelage permanent ; réserve de 99 % du calcium de l'organisme.") + H('Cellules') + UL(["<strong>Ostéoblastes</strong> : dérivés des cellules mésenchymateuses (facteur RUNX2), en bordure des travées, synthétisent l'ostéoïde et pilotent sa minéralisation (phosphatase alcaline) ; ils expriment le <strong>RANK-ligand</strong> qui active les ostéoclastes et l'ostéoprotégérine qui l'inhibe : ils commandent donc aussi la résorption.", "<strong>Ostéocytes</strong> : ostéoblastes emmurés dans des <strong>ostéoplastes</strong>, reliés par des prolongements dans des <strong>canalicules</strong> (jonctions gap) : réseau qui perçoit les contraintes mécaniques (mécanotransduction, sclérostine) et entretient la matrice.", "<strong>Ostéoclastes</strong> : cellules géantes multinucléées d'origine hématopoïétique (fusion de précurseurs monocytaires sous l'effet de M-CSF et RANK-L), logées dans les lacunes de Howship ; leur bordure en brosse acidifie (pompe à protons, anhydrase carbonique) et dissout le minéral, puis les enzymes (cathepsine K) digèrent le collagène.", "<strong>Cellules bordantes</strong> : ostéoblastes au repos tapissant les surfaces inactives."]) + H('Organisation') + P("L'<strong>os compact</strong> (cortical, 80 % de la masse) est fait d'<strong>ostéons</strong> (systèmes de Havers) : lamelles concentriques autour d'un canal de Havers contenant vaisseaux et nerfs, reliés par des canaux de Volkmann ; entre les ostéons, des lamelles interstitielles (restes d'ostéons remodelés). L'<strong>os spongieux</strong> (trabéculaire) est un réseau de travées lamellaires délimitant les espaces médullaires (moelle hématopoïétique ou adipeuse), nourri par diffusion. L'os <strong>réticulaire</strong> (tissé, non lamellaire), à fibres désordonnées, est l'os immature du fœtus, du cal de fracture et de la maladie de Paget. Le <strong>périoste</strong> (couche fibreuse externe, couche ostéogène interne) et l'<strong>endoste</strong> tapissent les surfaces.") + H('Ossification et croissance') + UL(["<strong>Ossification membranaire</strong> (intramembraneuse) : à partir d'un blastème mésenchymateux, les ostéoblastes déposent directement de l'os : os plats de la voûte du crâne, de la face, clavicule. Les fontanelles sont les zones non encore ossifiées.", "<strong>Ossification endochondrale</strong> : une maquette de cartilage hyalin est remplacée par de l'os : os longs, vertèbres, base du crâne. Point d'ossification primaire diaphysaire (vie fœtale), points secondaires épiphysaires (après la naissance). Entre eux persiste le <strong>cartilage de conjugaison</strong> (plaque de croissance), dont les zones successives (réserve, prolifération en colonnes, hypertrophie, calcification, ossification) assurent la croissance en longueur ; sa fermeture à la puberté (œstrogènes) arrête la croissance. La croissance en épaisseur est périostée (appositionnelle).", "Régulation : GH et IGF-1, hormones thyroïdiennes, stéroïdes sexuels, vitamine D, calcium, contraintes mécaniques."]) + H('Remodelage') + P("Chaque année, 10 % du squelette est renouvelé par des unités de remodelage : activation, résorption ostéoclastique (2-3 semaines), inversion, formation ostéoblastique (3 mois), minéralisation. Équilibre régulé par la PTH (résorption), la calcitonine, la vitamine D, les œstrogènes (freinent les ostéoclastes : l'<strong>ostéoporose</strong> post-ménopausique résulte de leur perte), les corticoïdes (freinent les ostéoblastes), l'activité physique. Les biphosphonates inhibent les ostéoclastes ; le dénosumab bloque RANK-L.") + KEY("Ostéoblaste construit, ostéoclaste détruit, ostéocyte surveille ; les ostéoblastes commandent les ostéoclastes par RANK-L. Membranaire pour le crâne, endochondrale pour les os longs ; la croissance en longueur passe par le cartilage de conjugaison, en épaisseur par le périoste.") },
  ] },

  'histo-musculaire': { introduction: "Trois tissus musculaires pour trois fonctions : le muscle strié squelettique pour le mouvement volontaire, le myocarde pour la pompe cardiaque, le muscle lisse pour les viscères et les vaisseaux. Ce cours détaille leur structure, du sarcomère au mécanisme de contraction, et leurs différences.", readTime: 25, sections: [
    { title: 'Le muscle strié squelettique', content: H('Organisation') + P("Un muscle est entouré d'<strong>épimysium</strong>, divisé en faisceaux par le <strong>périmysium</strong>, chaque fibre étant enveloppée d'<strong>endomysium</strong> (réticuline, capillaires, terminaisons nerveuses). Ces gaines conjonctives se prolongent par le tendon. La <strong>fibre musculaire</strong> est une cellule géante (10-100 µm de diamètre, jusqu'à 30 cm de long), <strong>multinucléée</strong> (des centaines de noyaux <strong>périphériques</strong>, sous le sarcolemme), issue de la fusion de myoblastes embryonnaires. Son cytoplasme (sarcoplasme) est rempli de <strong>myofibrilles</strong> parallèles, de mitochondries, de glycogène et de myoglobine.") + H('Le sarcomère') + P("Chaque myofibrille montre une striation transversale périodique due à l'alternance de bandes : le <strong>sarcomère</strong>, unité contractile, s'étend d'une <strong>strie Z</strong> à la suivante (2-3 µm). Les <strong>filaments fins</strong> d'actine (avec la tropomyosine qui masque les sites de fixation de la myosine, et le complexe troponine T, I, C) sont ancrés sur la strie Z par l'α-actinine ; les <strong>filaments épais</strong> de myosine II (têtes à activité ATPasique) occupent le centre, reliés à la ligne M et à la strie Z par la titine (élasticité). La <strong>bande A</strong> (anisotrope, sombre) correspond aux filaments épais et à leur chevauchement avec les fins ; la <strong>bande I</strong> (isotrope, claire) aux filaments fins seuls ; la <strong>zone H</strong> aux filaments épais seuls. Pendant la contraction, les filaments glissent : les bandes I et H se raccourcissent, la bande A garde sa longueur (théorie du glissement des filaments de Huxley). La dystrophine relie le cytosquelette au sarcolemme ; son absence cause la myopathie de Duchenne.") + H('Couplage excitation-contraction') + P("Le sarcolemme s'invagine en <strong>tubules T</strong> à la jonction des bandes A et I, flanqués de deux citernes terminales du <strong>réticulum sarcoplasmique</strong> (<strong>triade</strong>). Le PA parcourt les tubules T, active les récepteurs aux dihydropyridines (capteurs de voltage) mécaniquement couplés aux <strong>récepteurs à la ryanodine</strong> du réticulum : libération de Ca2+ dans le sarcoplasme. Le Ca2+ se fixe sur la <strong>troponine C</strong>, déplace la tropomyosine, démasque les sites de l'actine ; les têtes de myosine, chargées d'ADP + Pi, s'y fixent, pivotent (coup de force), libèrent l'ADP, se détachent grâce à un nouvel ATP qu'elles hydrolysent pour se réarmer : cycle des ponts. La relaxation suit le repompage du Ca2+ par la SERCA. Sans ATP, les ponts restent fixés : rigidité cadavérique.") + H('Types de fibres et adaptation') + TABLE(['Type', 'Couleur', 'Métabolisme', 'Contraction', 'Exemples'], [['I (lentes)', 'rouges (myoglobine, mitochondries, capillaires)', 'oxydatif', 'lente, résistante à la fatigue', 'muscles posturaux, marathon'], ['IIa', 'intermédiaires', 'oxydatif-glycolytique', 'rapide, assez résistante', 'sports mixtes'], ['IIx (IIb)', 'blanches', 'glycolytique', 'rapide, puissante, fatigable', 'sprint, muscles oculaires']]) + P("L'entraînement modifie le métabolisme et l'hypertrophie (augmentation du volume des fibres, pas de leur nombre). Les <strong>cellules satellites</strong>, cellules souches quiescentes entre la lame basale et le sarcolemme, assurent la réparation et l'hypertrophie en fusionnant avec les fibres ; la régénération reste limitée. Récepteurs sensoriels : fuseaux neuromusculaires (longueur, réflexe myotatique) et organes tendineux de Golgi (tension).") + KEY("Fibre = cellule multinucléée à noyaux périphériques ; sarcomère de strie Z à strie Z ; bande A constante, bandes I et H qui se raccourcissent. Ca2+ → troponine C → tropomyosine → ponts actine-myosine consommant l'ATP. Triade = tubule T + deux citernes.") },
    { title: 'Le muscle cardiaque', content: P("Le <strong>myocarde</strong> est strié comme le muscle squelettique (mêmes sarcomères) mais formé de <strong>cardiomyocytes</strong> distincts : cellules courtes (100 µm), <strong>ramifiées</strong>, à <strong>un ou deux noyaux centraux</strong>, riches en mitochondries (40 % du volume : métabolisme strictement aérobie, d'où la vulnérabilité à l'ischémie), avec un réticulum sarcoplasmique moins développé et des tubules T larges situés au niveau des stries Z (<strong>diades</strong>).") + H('Disques intercalaires') + P("Les cardiomyocytes sont attachés bout à bout par des <strong>disques intercalaires</strong>, visibles en escalier : portions transversales avec des <strong>fascia adherens</strong> (ancrage de l'actine) et des <strong>desmosomes</strong> (résistance aux tractions), portions longitudinales avec des <strong>jonctions gap</strong> (connexine 43) qui couplent électriquement les cellules. Le myocarde fonctionne ainsi comme un <strong>syncytium fonctionnel</strong> : l'excitation née du nœud sinusal se propage de cellule en cellule, et tout le muscle se contracte. Anatomiquement, ce n'est pas un syncytium vrai (cellules individualisées), contrairement à la fibre squelettique.") + H('Particularités fonctionnelles') + UL(["Contraction <strong>involontaire</strong>, rythmique, <strong>automatique</strong> : le tissu nodal (cellules cardionectrices pauvres en myofibrilles) engendre le rythme ; les fibres de Purkinje (grandes, claires, riches en glycogène) le conduisent.", "Dépendance au <strong>Ca2+ extracellulaire</strong> : l'entrée de Ca2+ par les canaux L pendant le plateau déclenche la libération de Ca2+ du réticulum (« calcium-induced calcium release »), d'où l'effet des inhibiteurs calciques et de la calcémie sur la contractilité.", "Longue période réfractaire : pas de tétanos.", "Fonction endocrine : les cardiomyocytes auriculaires sécrètent le <strong>peptide natriurétique</strong> (grains atriaux).", "<strong>Pas de cellules satellites</strong> ni de régénération notable : l'infarctus laisse une cicatrice fibreuse ; l'hypertrophie compensatrice concerne les cellules, pas leur nombre."]) + KEY("Cardiomyocyte : strié, mononucléé à noyau central, ramifié, disques intercalaires avec jonctions gap (syncytium fonctionnel), automatisme, dépendance au calcium extracellulaire, pas de régénération.") },
    { title: 'Le muscle lisse', content: P("Le muscle lisse forme la tunique musculaire des <strong>viscères creux</strong> (tube digestif, voies urinaires et génitales, bronches), la <strong>média des vaisseaux</strong>, le muscle arrecteur du poil, les muscles de l'iris et du corps ciliaire. Ses cellules sont <strong>fusiformes</strong> (20 à 500 µm), à <strong>noyau unique central</strong> en bâtonnet, sans striation.") + H('Appareil contractile') + P("Actine et myosine existent mais sans organisation en sarcomères : les filaments fins s'ancrent sur des <strong>corps denses</strong> cytoplasmiques et des <strong>plaques denses</strong> membranaires (équivalents des stries Z, riches en α-actinine), reliés par un réseau de filaments intermédiaires (desmine, vimentine) orientés en diagonale. La contraction raccourcit la cellule dans tous les axes et la déforme en tire-bouchon. Pas de tubules T mais des <strong>cavéoles</strong> ; réticulum sarcoplasmique peu développé ; le Ca2+ vient en bonne partie de l'extérieur.") + H('Mécanisme de contraction') + P("Il n'y a pas de troponine. Le Ca2+ se lie à la <strong>calmoduline</strong> ; le complexe active la <strong>kinase des chaînes légères de myosine</strong> (MLCK), qui phosphoryle la myosine et permet le cycle des ponts. La relaxation dépend de la phosphatase des chaînes légères (activée par le NO via le GMPc : vasodilatation) ; la voie Rho-kinase sensibilise au Ca2+. Contraction lente (ondes lentes du tube digestif), prolongée, économe en ATP (état de verrouillage, « latch »), capable de maintenir un tonus pendant des heures (sphincters, vaisseaux).") + H('Commande et types') + UL(["<strong>Unitaire</strong> (viscéral) : cellules couplées par des <strong>jonctions gap</strong>, contraction en masse, activité spontanée (cellules pacemaker, interstitielles de Cajal), modulée par le SNA : tube digestif, utérus, uretères, petits vaisseaux.", "<strong>Multi-unitaire</strong> : cellules indépendantes, chacune innervée, contrôle fin : iris, corps ciliaire, muscles arrecteurs, gros vaisseaux, canal déférent.", "Innervation par varicosités des fibres végétatives libérant à distance (pas de plaque motrice), sensibilité aux hormones (ocytocine, adrénaline), aux médiateurs locaux (NO, histamine, prostaglandines) et à l'<strong>étirement</strong> (réponse myogénique).", "Capacités de <strong>régénération</strong> (mitoses) et d'<strong>hypertrophie</strong> (utérus gravide), synthèse de collagène et d'élastine (les cellules musculaires lisses vasculaires fabriquent la matrice de la média, et prolifèrent dans l'athérosclérose)."]) + TABLE(['', 'Squelettique', 'Cardiaque', 'Lisse'], [['Cellule', 'fibre géante multinucléée', 'cellule ramifiée mono/binucléée', 'cellule fusiforme mononucléée'], ['Noyaux', 'périphériques', 'central', 'central'], ['Striation', 'oui', 'oui', 'non'], ['Régulation du Ca2+', 'troponine', 'troponine', 'calmoduline / MLCK'], ['Source de Ca2+', 'réticulum sarcoplasmique', 'extracellulaire + réticulum', 'surtout extracellulaire'], ['Jonctions gap', 'non', 'oui (disques intercalaires)', 'oui (unitaire)'], ['Commande', 'volontaire, somatique', 'automatisme, SNA', 'SNA, hormones, étirement'], ['Régénération', 'limitée (cellules satellites)', 'quasi nulle', 'bonne']]) + KEY("Lisse = fusiforme, sans strie, corps denses, calmoduline au lieu de troponine, commande végétative. Le tableau comparatif des trois muscles est un incontournable : noyaux, striation, régulation du calcium, jonctions gap, régénération.") },
  ] },

  'histo-nerveux': { introduction: "Le tissu nerveux associe des neurones, spécialisés dans la réception, l'intégration et la transmission de signaux, et des cellules gliales, plus nombreuses, qui les soutiennent, les isolent, les nourrissent et les défendent. Ce cours en décrit la structure, la myéline, l'organisation des nerfs et des méninges.", readTime: 24, sections: [
    { title: 'Le neurone', content: P("Le système nerveux compte environ 86 milliards de neurones, cellules <strong>post-mitotiques</strong> hautement polarisées, à durée de vie égale à celle de l'individu. Chaque neurone comprend :") + UL(["Le <strong>corps cellulaire</strong> (péricaryon, soma) : noyau volumineux et clair à nucléole proéminent, cytoplasme riche en réticulum endoplasmique granuleux organisé en amas basophiles, les <strong>corps de Nissl</strong> (synthèse protéique intense), appareil de Golgi, mitochondries, lysosomes, lipofuscine avec l'âge, cytosquelette de <strong>neurofilaments</strong> et de microtubules. Il reçoit des synapses.", "Les <strong>dendrites</strong> : prolongements courts, ramifiés, effilés, contenant des corps de Nissl, couverts d'<strong>épines dendritiques</strong> qui portent la plupart des synapses excitatrices : pôle de réception.", "L'<strong>axone</strong> : prolongement unique, né du <strong>cône d'émergence</strong> (sans Nissl), de diamètre constant, long (jusqu'à 1 m), se terminant par des ramifications et des <strong>boutons synaptiques</strong> ; il peut émettre des collatérales. L'axoplasme ne contient pas de ribosomes : tout est fabriqué dans le soma et transporté. <strong>Transport axonal</strong> antérograde (kinésine sur les microtubules : rapide pour les vésicules à 400 mm/j, lent pour le cytosquelette) et rétrograde (dynéine : recyclage, facteurs de croissance, mais aussi virus de la rage, de l'herpès, toxine tétanique)."]) + H('Classification') + UL(["Morphologique : <strong>multipolaires</strong> (plusieurs dendrites, un axone : motoneurones, pyramidales, Purkinje ; la grande majorité), <strong>bipolaires</strong> (une dendrite, un axone : rétine, muqueuse olfactive, ganglion cochléo-vestibulaire), <strong>pseudo-unipolaires</strong> (un prolongement unique qui se divise en T : neurones sensitifs des ganglions rachidiens et des ganglions des nerfs crâniens).", "Fonctionnelle : sensitifs (afférents), moteurs (efférents), <strong>interneurones</strong> (99 %, intégration, souvent inhibiteurs).", "Neurochimique : cholinergiques, glutamatergiques, GABAergiques, monoaminergiques, peptidergiques."]) + P("La <strong>synapse</strong> (voir le cours de physiologie) associe un bouton présynaptique riche en vésicules et mitochondries, une fente et une densité post-synaptique ; on distingue les synapses axo-dendritiques (les plus nombreuses, excitatrices), axo-somatiques (souvent inhibitrices) et axo-axoniques (modulatrices).") + KEY("Corps de Nissl dans le soma et les dendrites, jamais dans l'axone ni le cône d'émergence. Les neurones ne se divisent plus : la neurogenèse adulte reste marginale (hippocampe, bulbe olfactif). Le transport rétrograde explique la remontée des virus neurotropes.") },
    { title: 'Les cellules gliales', content: P("Les cellules gliales sont 5 à 10 fois plus nombreuses que les neurones, se divisent (d'où les tumeurs gliales : gliomes, la majorité des tumeurs cérébrales primitives) et n'engendrent pas de potentiel d'action.") + TABLE(['Cellule', 'Origine', 'Fonctions'], [['Astrocyte', 'neuroectoderme', 'soutien, <strong>barrière hémato-encéphalique</strong> (pieds astrocytaires autour des capillaires), nutrition (lactate), recapture du glutamate et du K+, régulation du milieu, cicatrice gliale (gliose) après lésion, participation à la synapse (tripartite). Protoplasmiques (substance grise) et fibreux (substance blanche), marqueur GFAP'], ['Oligodendrocyte', 'neuroectoderme', '<strong>myéline du SNC</strong> : un oligodendrocyte myélinise 20 à 50 segments d’axones différents'], ['Microglie', 'mésoderme (monocytes du sac vitellin)', 'macrophages résidents du SNC : surveillance, phagocytose, présentation d’antigène, inflammation, élagage synaptique'], ['Épendymocyte', 'neuroectoderme', 'épithélium cubique cilié bordant les ventricules et le canal épendymaire ; cellules des <strong>plexus choroïdes</strong> (sécrétion du LCR, 500 mL/jour, jonctions serrées : barrière sang-LCR) ; tanycytes'], ['Cellule de Schwann', 'crêtes neurales', '<strong>myéline du SNP</strong> : une cellule pour un seul segment d’un seul axone ; engaine aussi les fibres amyéliniques (plusieurs par cellule, sans enroulement) ; guide la régénération'], ['Cellule satellite (ganglionnaire)', 'crêtes neurales', 'entoure les corps cellulaires des ganglions, rôle de soutien et d’isolement']]) + H('La myéline') + P("La gaine de myéline résulte de l'<strong>enroulement</strong> de la membrane plasmique de la cellule gliale autour de l'axone (jusqu'à 100 tours), avec expulsion du cytoplasme : lamelles lipidiques (70 % de lipides : cholestérol, galactocérébrosides, sphingomyéline) et protéines (PLP et MBP dans le SNC, P0 et PMP22 dans le SNP). Elle est interrompue régulièrement aux <strong>nœuds de Ranvier</strong>, où l'axone est nu et concentre les canaux Na+ ; entre deux nœuds, un segment internodal (0,2-2 mm) correspond à une cellule de Schwann. Les incisures de Schmidt-Lanterman sont des résidus de cytoplasme. La myélinisation débute au 4e mois fœtal et se poursuit jusqu'à l'adolescence.") + P("Pathologies : <strong>sclérose en plaques</strong> (démyélinisation auto-immune du SNC, plaques périventriculaires, névrite optique), leucodystrophies (génétiques), <strong>syndrome de Guillain-Barré</strong> (polyradiculonévrite démyélinisante du SNP), maladie de Charcot-Marie-Tooth (PMP22), neuropathies diabétique et alcoolique.") + KEY("Oligodendrocyte : plusieurs axones, SNC ; cellule de Schwann : un segment d'un axone, SNP. Astrocyte = barrière hémato-encéphalique et homéostasie ; microglie = macrophage d'origine mésodermique ; épendymocyte = LCR.") },
    { title: 'Substance grise, substance blanche et nerfs', content: H('Système nerveux central') + P("La <strong>substance grise</strong> contient les corps cellulaires, les dendrites, les synapses et la glie : cortex cérébral (six couches) et cérébelleux (trois couches, cellules de Purkinje), noyaux gris, cornes de la moelle. La <strong>substance blanche</strong> est faite d'axones myélinisés (la myéline lui donne sa couleur) groupés en faisceaux et de glie : centre ovale, capsule interne, cordons de la moelle. Le <strong>neuropile</strong> est le feutrage de prolongements entre les corps cellulaires. Dans la moelle, la substance grise est centrale (papillon), la blanche périphérique ; dans l'encéphale, c'est l'inverse pour le cortex.") + H('Nerf périphérique') + P("Un nerf est un faisceau d'axones myélinisés et amyéliniques, sensitifs et moteurs, entourés de leurs cellules de Schwann, organisés en trois gaines conjonctives : l'<strong>endonèvre</strong> (réticuline et capillaires autour de chaque fibre), le <strong>périnèvre</strong> (couches concentriques de cellules aplaties à jonctions serrées formant une barrière autour de chaque fascicule) et l'<strong>épinèvre</strong> (conjonctif dense et adipeux englobant les fascicules et les vaisseaux, vasa nervorum). Les <strong>ganglions</strong> sont des amas de corps cellulaires hors du SNC : ganglions rachidiens sensitifs (neurones pseudo-unipolaires entourés de cellules satellites), ganglions végétatifs (neurones multipolaires).") + H('Dégénérescence et régénération') + P("Après section d'un axone périphérique, le segment distal dégénère (<strong>dégénérescence wallérienne</strong> : fragmentation de l'axone et de la myéline, phagocytose par les macrophages et les cellules de Schwann), le corps cellulaire réagit (chromatolyse : dispersion des corps de Nissl, noyau excentré). Les cellules de Schwann prolifèrent et forment des bandes de Büngner qui guident la repousse de l'axone depuis le moignon proximal, à 1-3 mm par jour ; la réinnervation est possible si les gaines sont conservées (suture nerveuse). Dans le SNC, la régénération échoue : cicatrice astrocytaire, inhibiteurs de la myéline (Nogo), absence de guidage.") + H('Méninges et LCR') + P("Trois enveloppes : la <strong>dure-mère</strong> (conjonctif dense, adhérente au crâne, dédoublée pour former les sinus veineux ; espace épidural rachidien), l'<strong>arachnoïde</strong> (avasculaire, reliée à la pie-mère par des trabécules ; l'<strong>espace sous-arachnoïdien</strong> contient le LCR et les vaisseaux ; villosités arachnoïdiennes résorbant le LCR dans les sinus) et la <strong>pie-mère</strong> (fine, adhérente au tissu nerveux, suit les sillons). Le LCR (150 mL, renouvelé 3-4 fois par jour) est produit par les plexus choroïdes, circule des ventricules latéraux au 4e ventricule puis dans l'espace sous-arachnoïdien ; il protège mécaniquement et chimiquement l'encéphale. Ponction lombaire sous L2 (fin de la moelle), méningite (inflammation), hydrocéphalie (obstacle à la circulation), hématome extradural (artère méningée), sous-dural (veines-ponts), hémorragie sous-arachnoïdienne (anévrisme).") + KEY("Endonèvre, périnèvre (barrière), épinèvre : trois gaines pour un nerf. Régénération possible en périphérie grâce aux cellules de Schwann, impossible dans le SNC. Dure-mère, arachnoïde, pie-mère : le LCR circule dans l'espace sous-arachnoïdien.") },
  ] },

  'histo-fecondation-s1': { introduction: "Tout commence par deux cellules haploïdes. Ce cours décrit la fabrication des gamètes chez l'homme et chez la femme, le cycle ovarien qui libère l'ovocyte, la fécondation étape par étape, puis la première semaine du développement jusqu'au blastocyste et au début de la nidation.", readTime: 27, sections: [
    { title: 'Spermatogenèse', content: P("La <strong>spermatogenèse</strong> se déroule dans les <strong>tubes séminifères</strong> du testicule, de la puberté à la fin de la vie, de façon continue, en environ <strong>74 jours</strong> (plus 10-14 jours de transit épididymaire), à raison de 100 à 200 millions de spermatozoïdes par jour. Elle exige une température inférieure de 2-3 °C à celle du corps (scrotum, plexus pampiniforme).") + H('Étapes') + UL(["<strong>Spermatogonies</strong> (2n) : cellules souches contre la lame basale ; spermatogonies A (renouvellement) et B (engagées), qui se divisent par mitose.", "<strong>Spermatocytes I</strong> (2n, 4C après réplication) : entrent en <strong>méiose I</strong> (longue prophase de 3 semaines : recombinaison) et donnent deux <strong>spermatocytes II</strong> (n, 2C), qui achèvent rapidement la <strong>méiose II</strong> : quatre <strong>spermatides</strong> (n, C) haploïdes, rondes.", "<strong>Spermiogenèse</strong> : différenciation sans division de la spermatide en spermatozoïde : condensation du noyau (protamines remplaçant les histones), formation de l'<strong>acrosome</strong> à partir du Golgi (enzymes : hyaluronidase, acrosine), développement du <strong>flagelle</strong> à partir du centriole distal (axonème 9 + 2), regroupement des mitochondries en manchon autour de la pièce intermédiaire, élimination du cytoplasme résiduel (corps résiduel phagocyté par Sertoli).", "Les cellules filles restent reliées par des ponts cytoplasmiques (syncytium) jusqu'à la spermiation, ce qui synchronise leur maturation."]) + H('Cellules de soutien et régulation') + P("Les <strong>cellules de Sertoli</strong>, de la lame basale à la lumière, entourent les cellules germinales : soutien et nutrition, phagocytose, sécrétion du fluide tubulaire, de l'ABP (androgen binding protein), de l'<strong>inhibine</strong> (freine la FSH) et de l'hormone antimüllérienne (vie fœtale) ; leurs jonctions serrées forment la <strong>barrière hémato-testiculaire</strong>, qui isole les cellules méiotiques haploïdes (antigènes étrangers) du système immunitaire et du sang. Les <strong>cellules de Leydig</strong>, dans l'interstitium, sécrètent la <strong>testostérone</strong> sous l'effet de la LH ; la FSH agit sur Sertoli. La spermatogenèse dépend d'une concentration intratesticulaire élevée de testostérone.") + H('Le spermatozoïde') + P("60 µm : <strong>tête</strong> (noyau condensé coiffé de l'acrosome), <strong>col</strong>, <strong>pièce intermédiaire</strong> (mitochondries), pièce principale et terminale du flagelle. Il acquiert sa mobilité dans l'épididyme et son pouvoir fécondant dans les voies génitales féminines (<strong>capacitation</strong> : remaniement membranaire, hyperactivation, quelques heures). Spermogramme normal : volume &gt; 1,5 mL, &gt; 15 millions/mL, &gt; 40 % mobiles, &gt; 4 % de formes normales.") + KEY("Spermatogonie → spermatocyte I → spermatocyte II → spermatide → spermatozoïde : 74 jours, en continu, quatre gamètes par méiose. Sertoli = soutien, barrière, inhibine (FSH) ; Leydig = testostérone (LH).") },
    { title: 'Ovogenèse et cycle ovarien', content: P("L'<strong>ovogenèse</strong> diffère profondément : elle commence pendant la vie fœtale, se bloque deux fois, est discontinue et cyclique, produit un seul gamète par méiose, et s'arrête à la ménopause.") + H('Chronologie') + UL(["Vie fœtale : les cellules germinales primordiales colonisent l'ovaire, se multiplient par mitose en <strong>ovogonies</strong> (7 millions au 5e mois), puis entrent en méiose I et se bloquent en <strong>prophase I</strong> (stade diplotène, « dictyé ») : <strong>ovocytes I</strong>, chacun entouré d'une couche de cellules folliculaires plates : <strong>follicule primordial</strong>. Il n'y en aura jamais plus : 1 à 2 millions à la naissance, 400 000 à la puberté, 400 ovulés au cours de la vie, le reste dégénère (atrésie).", "À partir de la puberté, à chaque cycle, une cohorte de follicules est recrutée et un seul devient dominant. Juste avant l'ovulation, sous l'effet du pic de LH, l'ovocyte I achève la <strong>méiose I</strong> : ovocyte II (n, 2C) et premier <strong>globule polaire</strong> (division asymétrique : tout le cytoplasme à l'ovocyte). L'ovocyte II commence la méiose II et se bloque en <strong>métaphase II</strong>.", "La <strong>méiose II</strong> ne s'achève qu'en cas de <strong>fécondation</strong> : expulsion du second globule polaire. Sans fécondation, l'ovocyte II dégénère en 24 h."]) + H('Folliculogenèse') + P("Follicule primordial (ovocyte I + cellules folliculaires aplaties) → <strong>primaire</strong> (cellules cubiques, apparition de la <strong>zone pellucide</strong>, glycoprotéines ZP1-3 sécrétées par l'ovocyte) → <strong>secondaire</strong> (plusieurs couches de cellules de la <strong>granulosa</strong>, thèque interne endocrine et externe fibreuse) → <strong>tertiaire</strong> ou antral (cavité remplie de liquide folliculaire, ovocyte dans le cumulus oophorus) → <strong>follicule de De Graaf</strong> mûr (2 cm, saillant à la surface de l'ovaire). Cette croissance dure plusieurs mois, indépendante des gonadotrophines au début, puis dépendante de la FSH.") + H('Cycle ovarien (28 jours)') + UL(["<strong>Phase folliculaire</strong> (J1-J14, variable) : la FSH stimule la croissance des follicules ; la thèque interne produit des androgènes (LH) que la granulosa aromatise en <strong>œstradiol</strong> (FSH) ; l'œstradiol freine FSH et LH (rétrocontrôle négatif) et fait proliférer l'endomètre. Sélection du follicule dominant.", "<strong>Ovulation</strong> (J14) : quand l'œstradiol dépasse un seuil pendant 48 h, le rétrocontrôle devient <strong>positif</strong> : <strong>pic de LH</strong> (et de FSH) 36 h avant l'ovulation ; reprise de la méiose, mucification du cumulus, rupture folliculaire, libération de l'ovocyte II entouré de la zone pellucide et de la corona radiata, captée par le pavillon de la trompe.", "<strong>Phase lutéale</strong> (J15-J28, fixe à 14 jours) : le follicule rompu devient le <strong>corps jaune</strong> (cellules lutéales riches en lipides), sécrétant <strong>progestérone</strong> et œstradiol sous l'effet de la LH : endomètre sécrétoire, glaire épaisse, température ↑ de 0,5 °C. Sans hCG, le corps jaune dégénère (corpus albicans) au bout de 14 jours, la chute hormonale déclenche les <strong>règles</strong>. En cas de grossesse, l'hCG embryonnaire maintient le corps jaune jusqu'à ce que le placenta prenne le relais (2e-3e mois)."]) + KEY("Deux blocages : prophase I dès la vie fœtale, métaphase II à l'ovulation ; achèvement seulement à la fécondation. Un seul ovocyte par méiose, deux globules polaires. Pic de LH = rétrocontrôle positif de l'œstradiol = ovulation 36 h plus tard. La phase lutéale dure toujours 14 jours.") },
    { title: 'La fécondation', content: P("La <strong>fécondation</strong> est la fusion d'un spermatozoïde et d'un ovocyte II, qui rétablit la diploïdie, détermine le sexe et déclenche le développement. Elle a lieu dans l'<strong>ampoule</strong> (tiers externe) de la trompe, dans les 24 heures qui suivent l'ovulation ; les spermatozoïdes survivent 2 à 5 jours dans les cryptes cervicales : la période fertile s'étend de 5 jours avant à 1 jour après l'ovulation.") + H('Étapes') + UL(["<strong>Ascension</strong> : sur 200 millions de spermatozoïdes déposés, quelques centaines atteignent l'ampoule (glaire cervicale filtrante en période ovulatoire, contractions utérines, chimiotactisme).", "<strong>Capacitation</strong> dans les voies génitales : retrait du cholestérol et des glycoprotéines de la membrane, hyperactivation du flagelle.", "Traversée de la <strong>corona radiata</strong> (hyaluronidase, mouvements).", "Fixation à la <strong>zone pellucide</strong> : reconnaissance spécifique d'espèce par ZP3 (et ZP2), déclenchant la <strong>réaction acrosomique</strong> : fusion de la membrane acrosomique externe et de la membrane plasmique, libération des enzymes (acrosine) qui percent un tunnel dans la zone.", "<strong>Fusion des membranes</strong> (Izumo sur le spermatozoïde, Juno sur l'ovocyte) : le noyau, le centriole et le flagelle entrent dans l'ovocyte ; les mitochondries paternelles sont détruites (hérédité mitochondriale maternelle).", "<strong>Activation de l'ovocyte</strong> : oscillations calciques → <strong>réaction corticale</strong> (exocytose des granules corticaux qui modifient la zone pellucide : blocage lent de la <strong>polyspermie</strong>, après un blocage rapide électrique) et <strong>achèvement de la méiose II</strong> (expulsion du 2e globule polaire).", "Formation des <strong>pronuclei</strong> mâle (décondensation, remplacement des protamines par des histones) et femelle, réplication de l'ADN, rapprochement et <strong>amphimixie</strong> (mélange des chromosomes sur le fuseau de la première mitose, sans fusion des enveloppes) : le <strong>zygote</strong> diploïde à 46 chromosomes, dont le sexe génétique dépend du gonosome paternel (X ou Y), est constitué environ 24 h après la pénétration."]) + P("Le centriole apporté par le spermatozoïde organise le premier fuseau. Le génome embryonnaire ne s'exprime qu'à partir du stade 4 à 8 cellules : jusque-là, l'embryon vit sur les ARN et protéines maternels stockés dans l'ovocyte. L'<strong>empreinte parentale</strong> (méthylation différentielle de certains gènes selon leur origine) rend les deux génomes non interchangeables : une môle hydatiforme (deux génomes paternels) ne donne que du trophoblaste.") + H('Assistance médicale à la procréation') + P("Insémination intra-utérine, <strong>fécondation in vitro</strong> (stimulation ovarienne par FSH, ponction des ovocytes, mise en contact avec les spermatozoïdes, transfert d'un embryon à J2-J5), <strong>ICSI</strong> (injection d'un spermatozoïde dans l'ovocyte, court-circuite zone pellucide et réaction acrosomique : infertilités masculines), vitrification des ovocytes et embryons, diagnostic préimplantatoire.") + KEY("Ampoule tubaire, dans les 24 h après l'ovulation. Réaction acrosomique déclenchée par ZP3, réaction corticale contre la polyspermie, achèvement de la méiose II, amphimixie. Le sexe est fixé par le spermatozoïde ; les mitochondries viennent de la mère.") },
    { title: 'Première semaine : segmentation, blastocyste, nidation', content: H('Segmentation') + P("Le zygote se divise par mitoses successives sans croissance (<strong>segmentation</strong>) : les cellules filles, ou <strong>blastomères</strong>, sont de plus en plus petites dans le volume fixe de la zone pellucide, tandis que l'embryon progresse dans la trompe vers l'utérus (cils, contractions). Stade 2 cellules à 30 h, 4 cellules à 40 h, 8 cellules à J3. Jusqu'au stade 8 cellules, les blastomères sont <strong>totipotents</strong> (jumeaux monozygotes par séparation précoce).") + UL(["<strong>Compaction</strong> (8-16 cellules, J3) : les blastomères s'aplatissent les uns contre les autres (E-cadhérine), établissent des jonctions serrées en périphérie ; première polarisation : cellules externes et internes.", "<strong>Morula</strong> (J4, 16-32 cellules, « mûre ») : arrivée dans la cavité utérine.", "<strong>Blastocyste</strong> (J5, ≈ 100 cellules) : les cellules externes pompent du liquide, creusant le <strong>blastocèle</strong> ; l'embryon comprend désormais le <strong>trophoblaste</strong> (couche externe, futur placenta et annexes) et la <strong>masse cellulaire interne</strong> ou bouton embryonnaire (au pôle embryonnaire, futur embryon proprement dit et amnios ; source des cellules souches embryonnaires pluripotentes).", "<strong>Éclosion</strong> (J5-J6) : le blastocyste sort de la zone pellucide (enzymes, expansion), condition nécessaire à l'implantation."]) + H('Nidation (implantation)') + P("Vers <strong>J6-J7</strong>, le blastocyste s'accole à l'endomètre par son pôle embryonnaire, le plus souvent sur la paroi <strong>postéro-supérieure du corps utérin</strong>. Trois conditions : un endomètre <strong>réceptif</strong> en phase sécrétoire (fenêtre d'implantation J20-J24 du cycle, sous progestérone : glandes tortueuses, artères spiralées, pinopodes), un blastocyste éclos et un dialogue moléculaire (intégrines, LIF, hCG). Le trophoblaste au contact prolifère et se différencie en <strong>cytotrophoblaste</strong> (couche interne, cellules individualisées mitotiques) et <strong>syncytiotrophoblaste</strong> (couche externe multinucléée, invasive, non mitotique), qui digère l'épithélium puis le stroma endométrial : le blastocyste s'enfouit progressivement (implantation interstitielle, achevée vers J12). Le stroma réagit par la <strong>décidualisation</strong> (cellules déciduales riches en glycogène et lipides). Le syncytiotrophoblaste sécrète dès J7-J8 l'<strong>hCG</strong>, qui maintient le corps jaune (dosable dans le sang dès J10, dans les urines quelques jours plus tard).") + H('Anomalies') + UL(["<strong>Grossesse extra-utérine</strong> (1-2 %) : nidation dans la trompe le plus souvent (séquelles d'infection, tabac), rupture hémorragique vers 6-8 semaines ; ovarienne, abdominale, cervicale plus rares.", "<strong>Placenta praevia</strong> : nidation trop basse, près du col.", "<strong>Môle hydatiforme</strong> : prolifération trophoblastique anormale (génome paternel double), hCG très élevée.", "Échecs d'implantation (la majorité des embryons aneuploïdes), fausses couches précoces (10-15 % des grossesses reconnues, 50 % de causes chromosomiques)."]) + KEY("J0 fécondation, J3 morula et compaction, J5 blastocyste (trophoblaste + bouton embryonnaire), J6-J7 début de nidation par le syncytiotrophoblaste, qui sécrète l'hCG. La fenêtre d'implantation est fixée par la progestérone.") },
  ] },

  'histo-s2-s3': { introduction: "Pendant les deuxième et troisième semaines, l'amas de cellules devient un disque organisé : deux feuillets d'abord, trois ensuite, avec des axes, une notochorde et les premières ébauches. La gastrulation est l'événement fondateur de tout le plan d'organisation du corps.", readTime: 26, sections: [
    { title: 'Deuxième semaine : le disque didermique', content: P("La deuxième semaine est celle de l'implantation complète et de la formation du <strong>disque embryonnaire didermique</strong>. On la résume par la « règle des deux » : deux couches de trophoblaste, deux feuillets embryonnaires, deux cavités, deux couches de mésoderme extra-embryonnaire.") + H('Évolution du trophoblaste') + UL(["Le <strong>syncytiotrophoblaste</strong> envahit l'endomètre ; vers J9 des <strong>lacunes</strong> s'y creusent, qui vers J11-J12 érodent les capillaires maternels et se remplissent de sang : première ébauche de la circulation utéro-placentaire (stade lacunaire). Il sécrète l'hCG.", "Le <strong>cytotrophoblaste</strong> prolifère et envoie, vers J13, des colonnes cellulaires dans le syncytium : <strong>villosités primaires</strong>, futures villosités choriales."]) + H('Évolution du bouton embryonnaire') + UL(["Vers J8, le bouton se différencie en deux feuillets accolés : l'<strong>épiblaste</strong> (cellules prismatiques, dorsal, côté trophoblaste) et l'<strong>hypoblaste</strong> (cellules cubiques, ventral, côté blastocèle) : disque didermique.", "Dans l'épiblaste apparaît la <strong>cavité amniotique</strong>, bordée par les amnioblastes (issus de l'épiblaste) : l'amnios.", "L'hypoblaste s'étend et tapisse le blastocèle (membrane de Heuser) : <strong>vésicule vitelline primitive</strong> (lécithocèle), remplacée vers J12-J13 par la <strong>vésicule vitelline secondaire</strong>, plus petite ; les restes de la primitive forment des kystes exocœlomiques.", "Le <strong>mésoderme extra-embryonnaire</strong> se développe entre le cytotrophoblaste et les deux vésicules, puis se creuse du <strong>cœlome extra-embryonnaire</strong> (cavité choriale), ne laissant qu'un pont, le <strong>pédicule embryonnaire</strong>, futur cordon ombilical. Le trophoblaste doublé de mésoderme constitue le <strong>chorion</strong>."]) + P("À la fin de la 2e semaine, l'embryon est un disque plat de 0,2 mm suspendu dans la cavité choriale, entre l'amnios (dorsal) et la vésicule vitelline (ventral), relié au chorion par le pédicule. Dans l'hypoblaste, à l'extrémité future crâniale, un épaississement, la <strong>plaque préchordale</strong>, marque déjà l'axe antéro-postérieur.") + KEY("Semaine 2 : épiblaste et hypoblaste, cavité amniotique et vésicule vitelline, cyto- et syncytiotrophoblaste, lacunes remplies de sang maternel, hCG. Le test de grossesse est positif avant la fin de cette semaine.") },
    { title: 'Troisième semaine : la gastrulation', content: P("La <strong>gastrulation</strong> transforme le disque didermique en disque tridermique et met en place les trois <strong>feuillets</strong> primordiaux, dont dériveront tous les tissus. Elle débute vers J15 par l'apparition, sur la face dorsale de l'épiblaste, de la <strong>ligne primitive</strong>, épaississement médian qui s'étend depuis le bord caudal vers le centre, terminé en avant par le <strong>nœud primitif</strong> (nœud de Hensen). La ligne primitive définit les axes : crânio-caudal, droite-gauche, dorsal-ventral.") + H('Mouvements cellulaires') + UL(["Les cellules épiblastiques migrent vers la ligne primitive, s'y <strong>invaginent</strong> (transition épithélio-mésenchymateuse, perte d'E-cadhérine) et gagnent l'espace sous-jacent.", "Les premières remplacent l'hypoblaste : <strong>endoderme</strong> définitif (l'hypoblaste est refoulé dans la vésicule vitelline).", "Les suivantes s'étalent entre épiblaste et endoderme : <strong>mésoderme intra-embryonnaire</strong>, qui envahit tout le disque sauf deux zones où épiblaste et endoderme restent accolés : la <strong>membrane pharyngienne</strong> (bucco-pharyngée, en avant) et la <strong>membrane cloacale</strong> (en arrière), qui se perforeront plus tard pour ouvrir la bouche et l'anus.", "L'épiblaste restant en surface devient l'<strong>ectoderme</strong>.", "Les cellules passant par le nœud primitif migrent vers l'avant sur la ligne médiane et forment le <strong>processus notochordal</strong>, qui devient la <strong>notochorde</strong> (chorde dorsale) : baguette mésodermique axiale, sous la ligne médiane de l'ectoderme, qui induit la plaque neurale et le sclérotome, puis persiste seulement dans le <strong>nucleus pulposus</strong> des disques intervertébraux.", "La ligne primitive régresse à la fin de la 4e semaine ; ses vestiges peuvent donner un tératome sacro-coccygien."]) + H('Différenciation du mésoderme') + P("De part et d'autre de la notochorde, le mésoderme s'organise en trois bandes longitudinales :") + UL(["<strong>Mésoderme para-axial</strong> : se segmente à partir de J20 en <strong>somites</strong> (paires de blocs, une paire toutes les 90 minutes environ, 42-44 paires à la fin de la 5e semaine, permettant de dater l'embryon), chacun se divisant en <strong>sclérotome</strong> (vertèbres, côtes), <strong>myotome</strong> (muscles squelettiques du tronc et des membres) et <strong>dermatome</strong> (derme du dos) ; la métamérie du corps (nerfs rachidiens) en découle.", "<strong>Mésoderme intermédiaire</strong> : appareil urinaire (pronéphros, mésonéphros, métanéphros) et gonades.", "<strong>Mésoderme latéral</strong> : se clive en <strong>somatopleure</strong> (contre l'ectoderme : paroi du corps, derme ventral, membres) et <strong>splanchnopleure</strong> (contre l'endoderme : paroi du tube digestif, cœur, vaisseaux, mésentères), séparées par le <strong>cœlome intra-embryonnaire</strong>, futures cavités péricardique, pleurales et péritonéale."]) + H('Autres événements de la 3e semaine') + P("<strong>Angiogenèse</strong> : îlots sanguins (îlots de Wolff et Pander) dans le mésoderme de la vésicule vitelline et du pédicule, puis dans l'embryon ; le <strong>tube cardiaque</strong> se forme dans l'aire cardiogène en avant de la membrane pharyngienne et bat dès J21-J22 : premier organe fonctionnel. L'<strong>allantoïde</strong> bourgeonne à J16 de la vésicule vitelline dans le pédicule. Le trophoblaste forme les villosités secondaires (axe mésodermique) puis <strong>tertiaires</strong> (capillaires fœtaux, J21) : la circulation fœto-placentaire est établie. La <strong>neurulation</strong> commence à la fin de la semaine.") + KEY("Ligne primitive → invagination de l'épiblaste → endoderme puis mésoderme, l'épiblaste résiduel devenant ectoderme. Notochorde = axe et inducteur. Mésoderme para-axial → somites (sclérotome, myotome, dermatome) ; intermédiaire → reins et gonades ; latéral → parois, cœur, séreuses.") },
    { title: 'Devenir des feuillets', content: TABLE(['Feuillet', 'Dérivés'], [['<strong>Ectoderme</strong> de surface', 'épiderme et ses annexes (poils, ongles, glandes sudoripares, sébacées, mammaires), émail dentaire, cristallin, cornée, épithélium de la bouche et des fosses nasales, adénohypophyse (poche de Rathke), oreille interne (placode otique)'], ['<strong>Neuroectoderme</strong> (tube neural)', 'encéphale, moelle épinière, rétine et nerf optique, neurohypophyse, épiphyse, motoneurones, oligodendrocytes, astrocytes, épendyme'], ['<strong>Crêtes neurales</strong>', 'ganglions sensitifs et végétatifs, nerfs périphériques et cellules de Schwann, médullosurrénale, mélanocytes, cellules C de la thyroïde, méninges (pie-mère, arachnoïde), os et cartilages de la face, dentine, septum aortico-pulmonaire, système nerveux entérique'], ['<strong>Mésoderme</strong>', 'tissus conjonctifs, cartilage, os, muscles (squelettiques, lisses, myocarde), cœur, vaisseaux, sang et moelle, reins et voies urinaires, gonades et voies génitales, cortex surrénalien, rate, séreuses, derme'], ['<strong>Endoderme</strong>', 'épithélium du tube digestif (de la bouche postérieure au rectum), foie, vésicule, pancréas, épithélium respiratoire (larynx, trachée, bronches, alvéoles), thyroïde, parathyroïdes, thymus, amygdales, oreille moyenne et trompe d’Eustache, vessie et urètre, vagin inférieur']]) + P("Retenir que les organes sont presque toujours mixtes : la paroi de l'intestin associe un épithélium endodermique et une musculeuse mésodermique ; la peau, un épiderme ectodermique et un derme mésodermique ; les dents, un émail ectodermique et une dentine issue des crêtes neurales. Les <strong>crêtes neurales</strong>, parfois qualifiées de « quatrième feuillet », donnent des dérivés d'une diversité surprenante et expliquent des associations pathologiques (neurocristopathies : maladie de Hirschsprung, syndromes de DiGeorge et de Waardenburg, neurofibromatose).") + H('Jumeaux') + UL(["<strong>Dizygotes</strong> (2/3) : deux ovulations, deux fécondations ; toujours deux chorions et deux amnios ; ressemblance de frères et sœurs.", "<strong>Monozygotes</strong> (1/3, 1 naissance sur 250) : un seul zygote scindé. Avant J3 (blastomères) : bichoriaux biamniotiques (30 %) ; entre J4 et J8 (bouton embryonnaire du blastocyste) : <strong>monochoriaux biamniotiques</strong> (65 %, risque de syndrome transfuseur-transfusé) ; après J8 (disque didermique) : monochoriaux monoamniotiques (rares, cordons emmêlés) ; après J13 (ligne primitive) : jumeaux conjoints."]) + KEY("Ectoderme = peau et système nerveux, mésoderme = tout ce qui soutient, bouge, circule et filtre, endoderme = tous les épithéliums du tube digestif et respiratoire et leurs glandes. La date de séparation des jumeaux monozygotes fixe le nombre de chorions et d'amnios.") },
  ] },

  'histo-neurulation-annexes': { introduction: "La quatrième semaine plie le disque en un cylindre et referme le tube neural ; en parallèle se mettent en place les annexes qui protègent et nourrissent l'embryon : amnios, vésicule vitelline, allantoïde, cordon et placenta. Ce cours en décrit la formation, la structure et les fonctions.", readTime: 27, sections: [
    { title: 'Neurulation', content: P("La <strong>neurulation</strong> est la formation du tube neural, ébauche du système nerveux central, à partir de l'ectoderme, sous l'induction de la notochorde et du mésoderme para-axial (signaux : inhibition des BMP par la noggine et la chordine, Shh ventral). Elle se déroule de J18 à J28.") + UL(["<strong>Plaque neurale</strong> (J18) : épaississement de l'ectoderme médian, en raquette, plus large en avant (futur encéphale).", "<strong>Gouttière neurale</strong> (J20) : les bords se soulèvent en <strong>bourrelets neuraux</strong> tandis que la ligne médiane se déprime.", "<strong>Tube neural</strong> (J22) : les bourrelets fusionnent sur la ligne médiane, d'abord dans la région cervicale (niveau des somites 4-6), la fermeture progressant en fermeture éclair vers la tête et la queue ; l'ectoderme de surface se referme au-dessus. Le tube reste ouvert aux deux extrémités : <strong>neuropore antérieur</strong> (fermé à J25) et <strong>neuropore postérieur</strong> (fermé à J27-J28) ; jusque-là, la lumière communique avec la cavité amniotique.", "Les cellules situées à la crête des bourrelets se détachent lors de la fermeture : <strong>crêtes neurales</strong>, qui migrent dans tout l'embryon (voir les dérivés).", "Le tube neural se dilate en avant en trois <strong>vésicules cérébrales primitives</strong> (prosencéphale, mésencéphale, rhombencéphale, J28), puis cinq (télencéphale, diencéphale, mésencéphale, métencéphale, myélencéphale, 5e semaine) ; la partie caudale reste tubulaire : moelle. La lumière devient les ventricules et le canal épendymaire ; la paroi (neuroépithélium) prolifère et donne neurones puis glie."]) + H('Anomalies de fermeture') + P("Les <strong>défauts de fermeture du tube neural</strong> (1/1 000 naissances) résultent d'une fermeture incomplète : <strong>anencéphalie</strong> (neuropore antérieur : absence de voûte crânienne et d'hémisphères, létale), <strong>spina bifida</strong> (neuropore postérieur : de la forme occulte à la myéloméningocèle lombo-sacrée avec paralysie et incontinence), encéphalocèle, craniorachischisis. Facteurs : carence en <strong>acide folique</strong>, valproate et carbamazépine, diabète maternel, hyperthermie, prédisposition génétique. Prévention par la supplémentation en folates (0,4 mg/j, 5 mg si antécédent) <strong>dès le projet de grossesse</strong>, puisque la fermeture est achevée avant que la grossesse ne soit souvent connue. Dépistage : α-fœtoprotéine maternelle élevée, échographie.") + KEY("Plaque, gouttière, tube : fermeture de J22 à J28, cervicale d'abord, neuropores antérieur (J25) puis postérieur (J28). Anencéphalie en avant, spina bifida en arrière ; les folates avant la conception.") },
    { title: 'Délimitation de l’embryon', content: P("Au cours de la 4e semaine, la croissance rapide du disque (surtout du tube neural et des somites) par rapport à la vésicule vitelline, qui ne grandit pas, provoque une <strong>plicature</strong> dans deux plans : le disque plat devient un embryon cylindrique, l'ectoderme en surface, l'endoderme en tube central, le mésoderme entre les deux.") + UL(["<strong>Plicature longitudinale</strong> (crânio-caudale) : le pli céphalique fait basculer l'aire cardiaque et la membrane pharyngienne sous la tête (le cœur, d'abord en avant de l'embryon, se retrouve en position thoracique ventrale) et forme l'<strong>intestin antérieur</strong> ; le pli caudal ramène la membrane cloacale et l'allantoïde sur la face ventrale et forme l'<strong>intestin postérieur</strong>.", "<strong>Plicature transversale</strong> : les bords latéraux du disque s'enroulent ventralement et se rejoignent sur la ligne médiane ventrale, pinçant l'endoderme en un tube, l'<strong>intestin primitif</strong>, dont la partie moyenne reste reliée à la vésicule vitelline par le <strong>canal vitellin</strong>. La somatopleure forme la paroi du corps, la splanchnopleure la paroi de l'intestin ; le cœlome intra-embryonnaire devient les cavités péricardique, pleurales et péritonéale.", "L'<strong>amnios</strong>, solidaire des bords du disque, suit le mouvement et enveloppe tout l'embryon ; il englobe le pédicule embryonnaire et le canal vitellin dans une gaine : le <strong>cordon ombilical</strong>. La cavité amniotique grandit jusqu'à oblitérer le cœlome extra-embryonnaire (fusion amnios-chorion vers le 3e mois)."]) + P("À la fin de la 4e semaine, l'embryon (4-5 mm) présente un tube neural fermé, 30 paires de somites, un cœur qui bat, des arcs pharyngiens, les bourgeons des membres supérieurs, les placodes optiques et otiques, un intestin primitif à trois segments, et il est recourbé en C.") + KEY("Plicature longitudinale (tête et queue) et transversale (côtés) : le cœur passe devant le thorax, l'intestin devient un tube relié à la vésicule vitelline par le canal vitellin, l'amnios enveloppe tout et forme le cordon.") },
    { title: 'Amnios, vésicule vitelline, allantoïde, cordon', content: H('Amnios et liquide amniotique') + P("Membrane avasculaire (amnioblastes épithéliaux sur un mésenchyme), délimitant la <strong>cavité amniotique</strong> remplie de <strong>liquide amniotique</strong> : 30 mL à 10 semaines, 800 mL à 1 L vers 34-36 semaines, produit d'abord par ultrafiltration du plasma maternel et fœtal, puis surtout par les <strong>urines fœtales</strong> (dès la 12e semaine) et les sécrétions pulmonaires, résorbé par la déglutition fœtale et les membranes ; renouvelé toutes les 3 heures. Fonctions : protection mécanique et thermique, liberté de mouvement (développement musculaire et squelettique), développement pulmonaire, prévention des adhérences, barrière contre l'infection. <strong>Oligoamnios</strong> (agénésie rénale, rupture des membranes : hypoplasie pulmonaire, déformations), <strong>hydramnios</strong> (atrésie de l'œsophage, anencéphalie, diabète). L'<strong>amniocentèse</strong> (15-18 SA) prélève des cellules fœtales desquamées pour le caryotype.") + H('Vésicule vitelline') + P("Sans réserve nutritive chez l'homme (contrairement aux oiseaux), mais indispensable : siège de l'<strong>hématopoïèse primitive</strong> (îlots sanguins, 3e-6e semaine, avant le foie puis la moelle), origine des <strong>cellules germinales primordiales</strong> (qui migrent vers les crêtes génitales à la 5e semaine), formation de l'intestin primitif. Elle régresse, reliée à l'intestin moyen par le canal vitellin, dont la persistance donne le <strong>diverticule de Meckel</strong> (2 % de la population, iléon, à 60 cm de la valvule).") + H('Allantoïde') + P("Diverticule endodermique de la vésicule vitelline dans le pédicule embryonnaire (J16), rudimentaire chez l'homme : sa paroi mésodermique donne les <strong>vaisseaux ombilicaux</strong> ; sa partie intra-embryonnaire participe à la vessie ; le reste s'oblitère en <strong>ouraque</strong> (ligament ombilical médian), dont la persistance donne une fistule ombilicale.") + H('Cordon ombilical') + P("Formé par l'amnios enveloppant le pédicule embryonnaire, le canal vitellin et l'allantoïde. À terme : 50-60 cm, 1-2 cm de diamètre, spiralé, contenant <strong>deux artères ombilicales</strong> (sang fœtal pauvre en O2 vers le placenta, issues des artères iliaques internes) et <strong>une veine ombilicale</strong> (sang oxygéné vers le fœtus, rejoignant la veine cave par le canal d'Arantius) dans la <strong>gelée de Wharton</strong> (tissu conjonctif muqueux protecteur). Une artère ombilicale unique s'associe à des malformations. Après la naissance, les vaisseaux s'oblitèrent en ligaments.") + KEY("Liquide amniotique = urines fœtales, résorbé par déglutition : oligoamnios si le rein manque, hydramnios si l'œsophage est bouché. Cordon : deux artères, une veine, gelée de Wharton. Vésicule vitelline : premier sang et cellules germinales.") },
    { title: 'Le placenta', content: P("Organe d'échange transitoire, discoïde, de 500 g et 20 cm à terme, formé d'une partie fœtale (chorion villeux, plaque choriale) et d'une partie maternelle (décidue basale, plaque basale). C'est un placenta <strong>hémochorial</strong> : le sang maternel baigne directement les villosités fœtales, sans jamais se mélanger au sang fœtal.") + H('Formation') + UL(["Villosités primaires (cytotrophoblaste, J13), secondaires (axe mésodermique, J16), <strong>tertiaires</strong> (capillaires fœtaux, J21) : villosités crampons ancrées dans la décidue par la coque cytotrophoblastique, villosités libres flottant dans les <strong>chambres intervilleuses</strong> alimentées par les artères spiralées maternelles (remaniées par le trophoblaste extravilleux : perte de la paroi musculaire, bas débit et basse résistance ; un remaniement insuffisant cause la prééclampsie).", "Le chorion villeux se limite au pôle embryonnaire (<strong>chorion frondosum</strong>, en regard de la décidue basale) tandis que le reste s'atrophie (chorion laeve, en regard de la décidue capsulaire) ; la décidue pariétale tapisse le reste de l'utérus.", "Le placenta est divisé en 15-20 <strong>cotylédons</strong> par les septa intercotylédonaires maternels. Il est achevé à la fin du 4e mois puis grandit."]) + H('La barrière placentaire') + P("Entre sang maternel et sang fœtal : syncytiotrophoblaste, cytotrophoblaste (discontinu après le 4e mois), lame basale, mésenchyme villositaire, endothélium fœtal ; elle s'amincit à 3-4 µm en fin de grossesse (membrane vasculo-syncytiale). Elle est <strong>sélective mais imparfaite</strong> : passent par diffusion O2, CO2, eau, urée, la plupart des médicaments et toxiques (alcool, nicotine, opioïdes), les virus (rubéole, CMV, Zika, VIH), le toxoplasme, le tréponème ; par transport actif ou facilité le glucose (GLUT1), les acides aminés, le fer, le calcium ; par transcytose les <strong>IgG</strong> maternelles (immunité passive du nouveau-né, surtout au 3e trimestre), mais pas les IgM ; ne passent pas les grosses protéines, l'héparine, l'insuline, la majorité des bactéries, les hématies (sauf micro-hémorragies : allo-immunisation rhésus).") + H('Fonctions') + UL(["<strong>Échanges</strong> respiratoires (le placenta est le poumon fœtal ; hémoglobine fœtale à forte affinité), nutritifs, excrétoires (urée, créatinine vers la mère).", "<strong>Endocrine</strong> (syncytiotrophoblaste) : <strong>hCG</strong> (maximum à 8-10 semaines, maintien du corps jaune, stimulation des cellules de Leydig fœtales, base du test de grossesse), <strong>hormone lactogène placentaire</strong> (hPL, insulinorésistance maternelle : nutriments pour le fœtus), <strong>progestérone</strong> (relais du corps jaune dès la 8e-10e semaine, quiescence utérine, indispensable) et <strong>œstrogènes</strong> (œstriol, à partir d'androgènes de la surrénale fœtale : unité fœto-placentaire), PAPP-A et autres marqueurs sériques du dépistage.", "<strong>Immunologique</strong> : tolérance de la semi-allogreffe fœtale (absence de HLA classiques sur le trophoblaste, HLA-G, cellules NK déciduales, lymphocytes T régulateurs), transfert des IgG."]) + H('Pathologie') + P("Prééclampsie (hypertension et protéinurie après 20 SA, d'origine placentaire), retard de croissance intra-utérin, hématome rétroplacentaire, placenta praevia, placenta accreta (invasion du myomètre), chorioamniotite, anomalies de la délivrance. Le placenta est examiné après l'accouchement (délivrance, 3e phase du travail).") + KEY("Hémochorial : sang maternel contre le syncytiotrophoblaste, sans mélange. Passent les gaz, les nutriments, la plupart des médicaments et virus, et les IgG ; pas les IgM ni l'héparine. hCG d'abord, progestérone placentaire après le 2e mois.") },
  ] },

  'histo-periode-embryonnaire': { introduction: "Après la gastrulation vient l'organogenèse, qui met en place tous les organes entre la 4e et la 8e semaine, puis la période fœtale, faite de croissance et de maturation. Ce cours fixe le calendrier, les repères du dépistage et les règles de la tératogenèse.", readTime: 25, sections: [
    { title: 'Calendrier du développement', content: H('Datation') + P("Deux références coexistent, source classique de confusion : les <strong>semaines de développement</strong> (ou de grossesse, comptées depuis la fécondation) et les <strong>semaines d'aménorrhée</strong> (SA, comptées depuis le premier jour des dernières règles, soit deux semaines de plus, car l'ovulation survient au 14e jour). L'obstétrique parle en SA : terme à <strong>41 SA</strong> (39 semaines de développement, 280 jours d'aménorrhée), prématurité avant 37 SA, viabilité à partir de 22-24 SA et 500 g. Les trimestres : 1er jusqu'à 14 SA, 2e de 15 à 28, 3e après. L'échographie du 1er trimestre (11-14 SA) date la grossesse à ± 5 jours par la longueur crânio-caudale.") + H('Période embryonnaire (semaines 1 à 8)') + P("Elle comprend la période pré-embryonnaire (semaines 1-3 : segmentation, nidation, gastrulation) et l'<strong>organogenèse</strong> (semaines 4-8) : tous les organes sont ébauchés, l'embryon passe de 4 mm à 3 cm et prend un aspect humain. Repères :") + UL(["<strong>Semaine 4</strong> : neurulation, plicature, cœur battant (J22), somites, arcs pharyngiens, bourgeons des membres supérieurs (J26) puis inférieurs (J28), placodes.", "<strong>Semaine 5</strong> : bourgeons des membres en palettes, vésicules cérébrales secondaires, ébauches du foie, du pancréas, des reins définitifs (métanéphros), migration des cellules germinales.", "<strong>Semaine 6</strong> : rayons digitaux, pavillon de l'oreille, pigmentation de la rétine, hernie ombilicale physiologique de l'intestin (jusqu'à la 10e semaine), cloisonnement du cœur.", "<strong>Semaine 7</strong> : doigts séparés (apoptose des espaces interdigitaux), différenciation gonadique (gène <strong>SRY</strong> : testicule), palais, paupières.", "<strong>Semaine 8</strong> : aspect humain, membres achevés, ossification qui débute, différenciation sexuelle externe qui commence (testostérone), fin de l'organogenèse."]) + H('Période fœtale (9e semaine à la naissance)') + P("<strong>Croissance</strong> (poids multiplié par 100 : de 30 g à 3,3 kg) et <strong>maturation</strong> fonctionnelle : mouvements dès 8 semaines (perçus par la mère vers 18-20 SA), déglutition et urines (12 semaines), sexe externe reconnaissable à l'échographie (14-16 SA), audition (20 SA), <strong>surfactant</strong> à partir de 24-28 SA (mature à 34-36 : le facteur limitant de la survie des prématurés), vernix et lanugo, ouverture des yeux (26 semaines), descente des testicules (7e-8e mois), myélinisation, réserves de graisse au dernier trimestre. Le fœtus est protégé des malformations majeures mais reste vulnérable aux atteintes fonctionnelles, au retard de croissance et aux toxiques neurologiques.") + KEY("Semaines d'aménorrhée = développement + 2. Organogenèse = semaines 4 à 8 de développement ; cœur à J22, membres à J26-28, SRY à la 7e semaine, aspect humain à la 8e. Après, on grandit et on mûrit.") },
    { title: 'Tératogenèse : principes', content: P("Un <strong>tératogène</strong> est un agent capable de provoquer une anomalie du développement. La <strong>tératologie</strong> obéit à quelques principes (Wilson) : la sensibilité dépend du <strong>stade</strong> de développement, du <strong>génotype</strong> de l'embryon et de la mère, de la <strong>dose</strong> et de la durée d'exposition, et du <strong>mécanisme</strong> propre à l'agent ; les manifestations vont de la mort à la malformation, au retard de croissance et aux déficits fonctionnels.") + H('Périodes de sensibilité') + TABLE(['Période', 'Stade', 'Effet d’une agression'], [['Semaines 1-2 (péri-implantatoire)', 'segmentation, blastocyste, disque didermique', '<strong>loi du tout ou rien</strong> : mort de l’embryon (fausse couche souvent inaperçue) ou réparation complète grâce à la totipotence des cellules ; pas de malformation'], ['Semaines 3-8 (embryonnaire)', 'gastrulation et organogenèse', '<strong>malformations majeures</strong> ; chaque organe a sa fenêtre de sensibilité maximale : SNC 3-5, cœur 3-6, membres 4-7, oreille 4-9, yeux 4-8, dents 6-8, organes génitaux 7-9 ; le thalidomide entre J20 et J36 donne la phocomélie'], ['Semaines 9-38 (fœtale)', 'croissance et maturation', 'anomalies fonctionnelles (SNC, comportement), retard de croissance, malformations mineures, atteintes des organes encore en développement (cerveau, dents, organes génitaux, oreille), toxicité néonatale']]) + H('Mécanismes') + UL(["<strong>Malformation</strong> : anomalie intrinsèque et primitive d'un processus de développement (spina bifida, fente labio-palatine, cardiopathie congénitale, agénésie rénale).", "<strong>Disruption</strong> : destruction secondaire d'une structure normalement formée (brides amniotiques amputant un membre, accident vasculaire fœtal, infection).", "<strong>Déformation</strong> : contrainte mécanique sur une structure normale (pied bot, plagiocéphalie par oligoamnios ou utérus malformé).", "<strong>Dysplasie</strong> : organisation anormale des cellules d'un tissu (dysplasies squelettiques).", "Une <strong>séquence</strong> est une cascade de conséquences d'une anomalie initiale (séquence de Potter : agénésie rénale → oligoamnios → hypoplasie pulmonaire, faciès, pieds bots) ; un <strong>syndrome</strong>, un ensemble d'anomalies de cause commune (trisomie 21, alcoolisation fœtale)."]) + P("Environ 3 % des nouveau-nés ont une malformation majeure ; causes : chromosomiques 10 %, géniques 20 %, environnementales (tératogènes) 5-10 %, multifactorielles et inconnues 60 %.") + KEY("Tout ou rien avant J14, malformations de la 3e à la 8e semaine (la période où la grossesse est souvent ignorée), atteintes fonctionnelles et de croissance ensuite. Malformation, disruption, déformation : trois mécanismes à distinguer.") },
    { title: 'Principaux tératogènes', content: H('Médicaments') + UL(["<strong>Thalidomide</strong> (1957-1961) : phocomélie et malformations viscérales chez 10 000 enfants ; à l'origine de la pharmacovigilance moderne. Réintroduit sous contrôle strict (myélome, lèpre).", "<strong>Isotrétinoïne</strong> (acné) et rétinoïdes : malformations cranio-faciales, cardiaques, du SNC dans 30 % des cas ; contraception obligatoire et test de grossesse mensuel.", "<strong>Acide valproïque</strong> : spina bifida (1-2 %), malformations cardiaques, troubles neurodéveloppementaux (30-40 % : autisme, QI abaissé) ; interdit chez la femme en âge de procréer sans alternative ni contraception. Carbamazépine, phénytoïne, phénobarbital : risque moindre mais réel.", "<strong>Antivitamines K</strong> : embryopathie (hypoplasie nasale, chondrodysplasie ponctuée) entre 6 et 9 semaines, hémorragies fœtales ; relais par héparine.", "<strong>IEC et sartans</strong> : atteinte rénale fœtale, oligoamnios, hypoplasie pulmonaire, mort (2e-3e trimestres).", "<strong>Méthotrexate</strong>, mycophénolate, cyclophosphamide, <strong>lithium</strong> (cardiopathie d'Ebstein), <strong>misoprostol</strong>, <strong>diéthylstilbestrol</strong> (Distilbène : adénocarcinome vaginal et malformations utérines chez les filles exposées in utero, effet transgénérationnel), <strong>androgènes</strong> (virilisation d'un fœtus féminin), tétracyclines (dents), aminosides (surdité), AINS après 24 SA (canal artériel, reins)."]) + H('Toxiques et environnement') + UL(["<strong>Alcool</strong> : première cause évitable de déficience intellectuelle ; <strong>syndrome d'alcoolisation fœtale</strong> (retard de croissance, dysmorphie faciale : fentes palpébrales courtes, philtrum lisse, lèvre supérieure fine ; microcéphalie, troubles cognitifs et comportementaux) ; pas de seuil connu : zéro alcool pendant la grossesse.", "<strong>Tabac</strong> : retard de croissance, prématurité, mort fœtale, mort subite du nourrisson, fentes ; <strong>cannabis, cocaïne</strong> (disruptions vasculaires), <strong>opioïdes</strong> (syndrome de sevrage néonatal).", "<strong>Radiations ionisantes</strong> : microcéphalie et retard mental (8-15 semaines les plus sensibles), à forte dose (&gt; 100 mGy ; un examen diagnostique reste très en dessous) ; <strong>hyperthermie</strong> maternelle (sauna, fièvre élevée : défauts du tube neural).", "<strong>Métaux et polluants</strong> : mercure (Minamata : atteinte neurologique), plomb, solvants, perturbateurs endocriniens."]) + H('Infections (TORCH) et maladies maternelles') + UL(["<strong>Toxoplasmose</strong> (chat, viande crue : hydrocéphalie, calcifications, choriorétinite ; sérologie et prévention), <strong>rubéole</strong> (1er trimestre : cardiopathie, cataracte, surdité ; vaccination avant la grossesse), <strong>cytomégalovirus</strong> (première cause de surdité congénitale non génétique, microcéphalie), <strong>herpès</strong> (à l'accouchement), <strong>syphilis</strong>, <strong>varicelle</strong>, <strong>parvovirus B19</strong> (anasarque), <strong>Zika</strong> (microcéphalie), VIH et hépatite B (transmission périnatale).", "<strong>Diabète maternel</strong> mal équilibré : malformations cardiaques et neurales (hyperglycémie du 1er trimestre), macrosomie, hypoglycémie néonatale ; <strong>phénylcétonurie</strong> non traitée ; carence en folates, en iode ; hypothyroïdie ; lupus (bloc auriculo-ventriculaire congénital par anticorps anti-SSA)."]) + H('Dépistage et diagnostic prénatal') + P("Échographies à 12, 22 et 32 SA (morphologie, croissance, clarté nucale). <strong>Dépistage combiné de la trisomie 21</strong> au 1er trimestre (clarté nucale + PAPP-A et β-hCG libre + âge maternel) puis <strong>ADN fœtal libre circulant</strong> dans le sang maternel si risque intermédiaire ; diagnostic par caryotype sur biopsie de trophoblaste (11-14 SA) ou amniocentèse (à partir de 15 SA), avec un risque de fausse couche de 0,5-1 %. Le <strong>CRAT</strong> (Centre de référence sur les agents tératogènes) est la source d'information de référence pour toute exposition pendant la grossesse.") + KEY("Alcool, valproate, isotrétinoïne, AVK, IEC, thalidomide, rétinoïdes : les tératogènes à connaître par cœur. Rubéole et toxoplasmose se préviennent avant ; le CMV est la première cause infectieuse de surdité. Le CRAT répond à toute question d'exposition.") },
  ] },
};
